// === Tab: mySketch ===
const Y_AXIS = 1;
const X_AXIS = 2;
let b1, b2, c1, c2;

let z = 0;
let points = [];
var force = 0.09;
var friction = 0.99;

function setup() {
	createCanvas(windowWidth, windowHeight);

		for(let y = 0; y < height; y+=15){
		points.push({
			x:Math.random() * width,
			y:Math.random() * height,
			vx:0,
			vy:0,
			pCol: createVector(Math.random()*205, 255, Math.random()*205),
			opac: Math.random()*255,
			dir: 0.01
		});
}

	// Define colors
  b1 = color(255);
  b2 = color(0);
  c1 = color(204, 102, 0);
  c2 = color(155, 22, 23);
}

function draw() {
	//background(99,37,33);
	  setGradient(0, 0, width / 2, height, c1, c2, X_AXIS);

		render();
}

function getValue(x, y) {
  var scale = 0.005;
  return noise(x * scale, y * scale, z) * Math.PI * 2;
}

function render() {

 for(let i = 0; i < points.length; i++) {

	  let p = points[i];
    let value = getValue(p.x, p.y);
    p.vx += Math.cos(value) * force;
    p.vy += Math.sin(value) * force;

  	stroke(p.pCol.x,p.pCol.y,p.pCol.z, p.opac+=p.dir);
  	strokeWeight(6);
	 	line(p.x, p.y, p.x+p.vx-8, p.y+p.vy);

	 if(p.opac>255)p.dir*=-1;
	  // add velocity to position
    p.x += p.vx;
    p.y += p.vy;
    // apply some friction so point doesn't speed up too much
    p.vx *= friction;
    p.vy *= friction;

	 // // wrap around edges of screen
     if(p.x > width ||
			 p.y > height ||
			 p.x < 0 ||
			 p.y < 0) 
		 {
				 p.x = width;
				 p.y = Math.random() * height;
 			}
 }

	z +=0.005;

// 				///// end point equations from angle and length
// 				let endX = Math.round(Math.cos(value) * lineLength + x);
// 				let endY = Math.round(Math.sin(value) * lineLength + y);

}

function setGradient(x, y, w, h, c1, c2, axis) {
  noFill();

  if (axis === Y_AXIS) {
    // Top to bottom gradient
    for (let i = y; i <= y + h; i++) {
      let inter = map(i, y, y + h, 0, 1);
      let c = lerpColor(c1, c2, inter);
      stroke(c);
      line(x, i, x + w, i);
    }
  } else if (axis === X_AXIS) {
    // Left to right gradient
    for (let i = x; i <= x + w; i++) {
      const inter = map(i, x, x + w, 0, 1);
      var c = lerpColor(c1, c2, inter);
      stroke(c);
      line(i, y, i, y + h);
    }
  }
}

